using System;using System.IO;using System.Collections.Generic;using System.Reflection;using Ashfall.Core;using Ashfall.Modules.Networking;using Ashfall.Modules.Sessions;using Ashfall.Integration.Playable.Networking;using Ashfall.Integration.Playable.Match;
partial class LobbyCases
{
 sealed class MaxWorld:IR24LanSpawnWorld{
  internal R24LanLobby Host;
  public bool ReadyForSpawn(string map,bool warmup){return true;}
  public SpawnSite[] Sites(string map,bool warmup){var rows=new SpawnSite[24];for(int i=0;i<24;i++)rows[i]=new SpawnSite("site"+i,warmup?R24LanSpawnCoordinates.Warmup(new Float3(0,0,0),i,false):R24LanSpawnCoordinates.BuiltinArena(new Float3(0,0,0),i),-1,false,false);return rows;}
  public bool IsSafe(string map,string actor,Float3 p){foreach(var m in Host.Members){R24LanSpawn s;if(m.Actor!=actor&&Host.TryReadSpawn(m.Actor,out s)){float x=s.Feet.X-p.X,z=s.Feet.Z-p.Z;if(x*x+z*z<.54f*.54f)return false;}}return true;}
 }
 static object InvokeMax(object owner,string name,params object[] args){return owner.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(owner,args);}
 static void MaxPlayerCases(){
  var defaults=R24PlayableMatchRules.ForPreset("team_respawn","range");Need(defaults.MaxPlayers==24,"Default 24");Need(defaults.With("max_players",1).MaxPlayers==2&&defaults.With("max_players",25).MaxPlayers==24,"Room limits clamp 2..24");
  MeasureMaxNetwork();MaxTwoRoom();foreach(int teams in new[]{0,2,3,4,5,6,7,8})MaxRoom(teams);
  Console.WriteLine("MAXPLAYERS: 24-member admission/25th refusal, late join, warmup/game placement, FFA/2 to 8 teams, score/equipment pages and personal results PASS");
 }
 static void MeasureMaxNetwork(){var transform=new R24LanTransform(new Float3(0,0,0),new R24LanRotation(0,0,0,1));string hash=new string('a',64);var pose=new R24LanPose("map:"+hash,0,1,transform,transform,transform,transform,new Float3(0,0,0),0,0);var raw=new R24LanRawTracking(hash,1,transform,transform,transform,transform,0,0);var packet=new Packet{Kind=PacketKind.Delta,ContentHash=hash,SessionId=new string('b',32),ActorId=new string('c',32),FeatureId="playable.presence/1",Payload=pose.Encode(),BaseSequence=-1};int presence=Wire.Encode(packet).Length;packet.FeatureId="playable.tracking/2";packet.Payload=raw.Encode();int tracking=Wire.Encode(packet).Length;Need(presence==421&&tracking==407,"Actual tracking wire lengths");foreach(int n in new[]{8,16,24})Console.WriteLine("NETWORK players="+n+" presenceBytes="+presence+" rawBytes="+tracking+" hostUploadBps="+((n-1)*(n-1)*25L*presence)+" hostDownloadBps="+((n-1)*25L*(presence+tracking)));}
 static void MaxTwoRoom(){var hp=new Pipe();var cp=new Pipe();int serial=0;string hash=new string('a',64);var host=new R24LanLobby(hp,hp.Close,delegate{return "small"+(++serial);},hash);var client=new R24LanLobby(cp,cp.Close,delegate{return "unused";},hash);hp.Lost=host.TransportDisconnected;cp.Lost=client.TransportDisconnected;
  try{host.StartHost("small","host","range",hash,2,R24PlayableMatchRules.ForPreset("team_respawn","range").With("max_players",2));hp.Links.Add("client",new Link{Remote=cp,Back="server"});cp.Links.Add("server",new Link{Remote=hp,Back="client"});client.StartClient("server","guest",0);host.TransportConnected("client");for(int i=0;i<5;i++){host.Tick(i*.05);client.Tick(i*.05);}Need(host.MemberCount==2&&client.RoomCapacity==2,"Two-seat room advertised/admitted");var extra=new Pipe();hp.Links.Add("extra",new Link{Remote=extra,Back="server"});extra.Links.Add("server",new Link{Remote=hp,Back="extra"});host.TransportConnected("extra");Need(!hp.Links.ContainsKey("extra")&&host.MemberCount==2,"Third refused in two-seat room");extra.Dispose();Need(host.BeginMapSelection("range",hash,R24PlayableMatchRules.ForPreset("team_respawn","range")),"Raise existing room cap");for(int i=5;i<10;i++){host.Tick(i*.05);client.Tick(i*.05);}Need(host.RoomCapacity==24&&client.RoomCapacity==24,"Client advertised capacity follows changed room rules");}finally{client.Dispose();host.Dispose();hp.Dispose();cp.Dispose();}}
 static void MaxRoom(int teams){
  var hp=new Pipe();int serial=0;string content=new string('a',64),hash=new string('b',64);var host=new R24LanLobby(hp,hp.Close,delegate{return (++serial).ToString("D64");},content);hp.Lost=host.TransportDisconnected;
  var rules=(teams==0?R24PlayableMatchRules.ForPreset("free_for_all","range"):R24PlayableMatchRules.ForPreset("team_respawn","range").With("teams",teams)).With("late_join",true).With("zone_enabled",false);host.StartHost("24","Host","range",hash,teams,rules);host.BindSpawnWorld(new MaxWorld{Host=host});
  var clients=new List<R24LanLobby>();var pipes=new List<Pipe>();double now=0;Action tick=delegate{now+=.05;host.Tick(now);foreach(var c in clients)c.Tick(now);};
  try{
   for(int n=0;n<23;n++){
    var pipe=new Pipe();var c=new R24LanLobby(pipe,pipe.Close,delegate{return "unused";},content);string key="max"+n;hp.Links.Add(key,new Link{Remote=pipe,Back="server"});pipe.Links.Add("server",new Link{Remote=hp,Back=key});pipe.Lost=c.TransportDisconnected;c.StartClient("server","Player "+n,now);host.TransportConnected(key);clients.Add(c);pipes.Add(pipe);for(int k=0;k<5;k++)tick();
    // Join the last sixteen after the warmup map is already active.
    if(n==6){Need(host.BeginMapSelection("range",hash)&&host.ReportMapLoaded(hash),"Warmup map selection");for(int k=0;k<5;k++)tick();foreach(var peer in clients)Need(peer.ReportMapLoaded(hash),"Initial warmup load");for(int k=0;k<5;k++)tick();}
    if(n>=7){Need(c.ReportMapLoaded(hash),"Late join world acknowledgment");for(int k=0;k<5;k++)tick();}
   }
   Need(host.MemberCount==24,"24 admitted including host");foreach(var c in clients)Need(c.MemberCount==24&&c.State==R24LanLobbyState.Connected,"24 complete roster on every client");
   var extra=new Pipe();hp.Links.Add("extra",new Link{Remote=extra,Back="server"});extra.Links.Add("server",new Link{Remote=hp,Back="extra"});host.TransportConnected("extra");Need(!hp.Links.ContainsKey("extra")&&host.MemberCount==24,"25th refused");extra.Dispose();
   Need(host.RequestSpawn(),"Host warmup spawn");foreach(var c in clients)Need(c.RequestSpawn(),"Guest warmup spawn");for(int k=0;k<12;k++)tick();CheckMaxSpawns(host);
   Need(host.BeginRoundSelection(rules,hash,23)&&host.ReportMapLoaded(hash),"24 round selection");for(int k=0;k<6;k++)tick();foreach(var c in clients)Need(c.ReportMapLoaded(hash),"24 round load");for(int k=0;k<85;k++)tick();
   Need(host.RequestSpawn(),"Host game spawn");foreach(var c in clients)Need(c.RequestSpawn(),"Guest game spawn");for(int k=0;k<12;k++)tick();CheckMaxSpawns(host);
   int[] counts=new int[Math.Max(1,teams)];foreach(var m in host.Members){Need(teams==0?m.Team==-1:m.Team>=0&&m.Team<teams,"Team index");if(teams>0)counts[m.Team]++;}foreach(int count in counts)if(teams>0)Need(count>=24/teams&&count<=(24+teams-1)/teams,"Balanced teams");
   var rows=new List<R24LanScoreRow>();var resultRows=new List<R26MatchEndRow>();var totals=new Dictionary<int,int>();int index=0;foreach(var m in host.Members){rows.Add(new R24LanScoreRow(m.Actor,m.Team,index,0,index));resultRows.Add(new R26MatchEndRow(m.Actor,m.Name,m.Team,index,0,index,0,0));index++;}
   InvokeMax(host,"PublishScorePages",rows);for(int k=0;k<8;k++)tick();foreach(var c in clients)foreach(var row in rows){R24LanScoreRow score;Need(c.TryReadScore(row.Actor,out score)&&score.Score==row.Score,"All 24 scores received atomically");}
   var result=R26MatchEndResults.Rank(now+10,false,resultRows,totals);foreach(var row in result.Rows){using(var stream=new MemoryStream())using(var writer=new BinaryWriter(stream)){writer.Write(0.0);writer.Write(now);typeof(R24LanLobby).GetMethod("WriteMatchEnd",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{writer,result,row.Actor});Need(stream.Length<=124,"Personal result bounded at 64-byte actor");stream.Position=16;using(var reader=new BinaryReader(stream)){var decoded=(R26MatchEndResults)typeof(R24LanLobby).GetMethod("ReadMatchEnd",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{reader});Need(decoded.ForActor(row.Actor).Rank==row.Rank,"Result rank through 24 roundtrip");}}}
   foreach(var c in clients)foreach(var m in host.Members){R26RemoteEquipment equip;Need(c.TryReadRemoteEquipment(m.Actor,out equip),"All 24 equipment rows received");}
   Need(host.HostFinishMatchWithCelebration(),"24-player actual finish");for(int k=0;k<48&&clients.Exists(c=>c.MatchEndResults==null);k++)tick();foreach(var c in clients)Need(c.MatchEndResults!=null&&c.MatchEndResults.Rows.Length==1&&c.MatchEndResults.ForActor(c.OwnActor)!=null,"Every client receives own final receipt after queued Health converges: teams="+teams+" actor="+c.OwnActor+" rejected="+c.RejectedFrames);
   Need(host.HostReturnAllPlayersToWarmupSpawns(),"24-player return to warmup");Need(host.ReportMapLoaded(hash),"Host reload acknowledgment");for(int k=0;k<5;k++)tick();foreach(var c in clients)Need(c.ReportMapLoaded(hash),"Warmup return load");for(int k=0;k<5;k++)tick();Need(host.RequestSpawn(),"Returned host spawn");foreach(var c in clients)Need(c.RequestSpawn(),"Returned guest spawn");for(int k=0;k<12;k++)tick();CheckMaxSpawns(host);
   Console.WriteLine("24 members teams="+teams+" maxPayload="+maxPayload+" maxPacket="+maxPacket);
  }finally{foreach(var c in clients)c.Dispose();host.Dispose();foreach(var p in pipes)p.Dispose();hp.Dispose();}
 }
 static int maxPayload,maxPacket;
 static void MaxFrame(Packet p,int bytes){maxPayload=Math.Max(maxPayload,p.Payload.Length);maxPacket=Math.Max(maxPacket,bytes);Need(p.Payload.Length<=512&&bytes<=1000,"Production frame MTU bounds");}
 static void CheckMaxSpawns(R24LanLobby host){var positions=new List<Float3>();foreach(var m in host.Members){R24LanSpawn spawn;Need(host.TryReadSpawn(m.Actor,out spawn),"All 24 placed");foreach(var p in positions){float x=p.X-spawn.Feet.X,z=p.Z-spawn.Feet.Z;Need(x*x+z*z>=.54f*.54f,"No overlapping committed spawns");}positions.Add(spawn.Feet);}Need(positions.Count==24,"24 distinct placements");}
}
